{
  "interpretation": {
    "name": "Line2NutrunnerTighteningWithEarlyReturn",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Bring the shared nutrunner NR7 to station st2, tighten the fasteners of variant F30, and send the tool back to the crib immediately after tightening while the evaluation and recording run in parallel.",
    "constraints": [
      "The tool must be reserved before use and released after it is back in the crib.",
      "The tool must be at the station before configure-tool and tighten-fasteners.",
      "The tightening program comes only from get-program; no process values appear in the Recipe.",
      "The tool returns to the crib right after tighten-fasteners, without waiting for evaluation or recording.",
      "The tightening must be evaluated and recorded (quality policy).",
      "transport-tool must be delegated to agvexecutor."
    ],
    "preference": "Minimise the time the shared tool is held by line 2.",
    "priority": "normal",
    "horizon": "Single execution, starting now.",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-nutrunner-tightening-early-return",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve-tool-step",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-program-step",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station-step",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "return-and-evaluate",
        "steps": [
          {
            "name": "configure-tool-step",
            "service": "configure-tool",
            "next": ["tighten-fasteners-step"],
            "dep": ["get-program-step", "reserve-tool-step", "transport-to-station-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-fasteners-step",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-tool-step", "reserve-tool-step", "transport-to-station-step"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-and-evaluate",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib-step",
            "service": "transport-tool",
            "next": ["release-tool-step"],
            "dep": ["reserve-tool-step"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-tool-step",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-tool-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "evaluate-tightening-step",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step", "get-program-step"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-tightening-step",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-fasteners-step"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
